            new() { Id = 2, CourseCode = "CS 201", Title = "Data Structures and Algorithms", Description = "Study of fundamental data structures (trees, graphs, hash tables) and algorithm design techniques (divide and conquer, dynamic programming).", Credits = 4, Schedule = "Tue/Thu 10:30–11:50 AM", InstructorName = "Dr. James Liu", InstructorBio = "Dr. Liu is a researcher in algorithm optimization with publications in top-tier conferences.", DepartmentId = 1, DepartmentName = "Computer Science", IsFeatured = true },
            new() { Id = 3, CourseCode = "CS 310", Title = "Database Systems", Description = "Design and implementation of relational databases, SQL, normalization, transaction management, and query optimization.", Credits = 3, Schedule = "Mon/Wed 2:00–3:20 PM", InstructorName = "Dr. Maria Garcia", InstructorBio = "Dr. Garcia specializes in distributed database systems and has industry experience at major tech companies.", DepartmentId = 1, DepartmentName = "Computer Science", IsFeatured = false },
